WITH lines AS (SELECT id, service, host, log_ts, latency_ms, status_code, key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS key, v) SELECT id, service, host, log_ts, key, MAX(status_code) OVER (PARTITION BY service, host ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) status_code_max_15m, COUNT(latency_ms) OVER (PARTITION BY host ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) latency_ms_count_30m FROM lines;
